//! The Pi vectors of pi-coding-agent's theme, keybinding-hint and visual-truncation helpers: what the pinned package's own functions return
//! (`test/parity/sdk-vectors/pi-coding-agent/<export>.json`, generated by `automation/gen/generate-sdk-vectors.mjs`). Every case of every file is run. A case
//! that needs the global theme or keybindings carries the palette and the table Pi ran with, which the test installs before it calls the SDK's own function.

use std::path::PathBuf;
use std::sync::Mutex;

use serde_json::Value;

use crate::tui::{KeybindingDefinition, KeybindingsManager, current_host_theme, set_keybindings};
use crate::{
    VisualKeep, get_editor_theme, get_markdown_theme, get_select_list_theme, get_settings_list_theme, key_hint, key_text, raw_key_hint, truncate_to_visual_lines,
};

/// The global theme and keybindings are process state: one test at a time installs them.
pub(crate) static STATE: Mutex<()> = Mutex::new(());

fn pi_cases(export: &str) -> Vec<Value> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../test/parity/sdk-vectors/pi-coding-agent").join(format!("{export}.json"));
    let value: Value = serde_json::from_slice(&std::fs::read(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()))).unwrap();
    let cases = value["cases"].as_array().unwrap().clone();
    assert!(!cases.is_empty(), "{export} has no cases");
    cases
}

/// The samples of `automation/gen/sdk-vector-lib/theme-state.mjs`; a vector's styles list one result per sample, in this order.
const SAMPLES: [&str; 12] = ["", "x", "to do it", "a\nb", "漢字", "\x1b[1m", "  ", "line\x1b[22m with close", "\x1b[3mi\x1b[23m", "multi\nline\x1b[1m\nbold", "a\r\nb", "\n"];

fn install_palette(palette: &Value) {
    crate::tui::set_host_theme(&Value::Null); // a host that published another palette first
    crate::tui::set_host_theme(palette);
}

fn strings(value: &Value) -> Vec<String> {
    value.as_array().unwrap().iter().map(|v| v.as_str().unwrap().to_string()).collect()
}

fn expect_samples(name: &str, key: &str, want: &Value, style: impl Fn(&str) -> String) {
    for (i, want) in strings(want).iter().enumerate() {
        assert_eq!(&style(SAMPLES[i]), want, "{name} {key}[{i}]");
    }
}

#[test]
fn markdown_theme_matches_pi() {
    let _guard = STATE.lock().unwrap_or_else(|e| e.into_inner());
    for case in pi_cases("getMarkdownTheme") {
        let (name, result) = (case["name"].as_str().unwrap(), &case["result"]);
        install_palette(&result["palette"]);
        let theme = get_markdown_theme();
        let styles: [(&str, &crate::StyleFn); 14] = [
            ("heading", &theme.heading), ("link", &theme.link), ("linkUrl", &theme.link_url), ("code", &theme.code), ("codeBlock", &theme.code_block),
            ("codeBlockBorder", &theme.code_block_border), ("quote", &theme.quote), ("quoteBorder", &theme.quote_border), ("hr", &theme.hr),
            ("listBullet", &theme.list_bullet), ("bold", &theme.bold), ("italic", &theme.italic), ("underline", &theme.underline),
            ("strikethrough", &theme.strikethrough),
        ];
        assert_eq!(result["styles"].as_object().unwrap().len(), styles.len(), "{name}: Pi's markdown theme has another set of styles");
        for (key, style) in styles {
            expect_samples(name, key, &result["styles"][key], |text| style(text));
        }
        // No language: Pi highlights nothing and the host is not asked.
        for entry in result["highlight"].as_array().unwrap() {
            if entry["lang"].as_str().is_none_or(str::is_empty) {
                let lines = (theme.highlight_code)(entry["code"].as_str().unwrap(), entry["lang"].as_str());
                assert_eq!(lines, strings(&entry["lines"]), "{name}: highlightCode without a language");
            }
        }
    }
}

#[test]
fn select_list_theme_matches_pi() {
    let _guard = STATE.lock().unwrap_or_else(|e| e.into_inner());
    for case in pi_cases("getSelectListTheme") {
        let (name, result) = (case["name"].as_str().unwrap(), &case["result"]);
        install_palette(&result["palette"]);
        let theme = get_select_list_theme();
        let styles: [(&str, &crate::StyleFn); 5] = [
            ("selectedPrefix", &theme.selected_prefix), ("selectedText", &theme.selected_text), ("description", &theme.description),
            ("scrollInfo", &theme.scroll_info), ("noMatch", &theme.no_match),
        ];
        assert_eq!(result["styles"].as_object().unwrap().len(), styles.len(), "{name}");
        for (key, style) in styles {
            expect_samples(name, key, &result["styles"][key], |text| style(text));
        }
        let editor = get_editor_theme();
        assert_eq!((editor.border_color)("x"), current_host_theme().fg("borderMuted", "x"), "{name}: editor border");
        assert_eq!((editor.select_list.selected_text)("x"), (theme.selected_text)("x"), "{name}: editor select list");
    }
}

#[test]
fn settings_list_theme_matches_pi() {
    let _guard = STATE.lock().unwrap_or_else(|e| e.into_inner());
    for case in pi_cases("getSettingsListTheme") {
        let (name, result) = (case["name"].as_str().unwrap(), &case["result"]);
        install_palette(&result["palette"]);
        let theme = get_settings_list_theme();
        assert_eq!(result["keys"].as_array().unwrap().len(), 5, "{name}");
        assert_eq!(theme.cursor, result["styles"]["cursor"].as_str().unwrap(), "{name}: cursor");
        expect_samples(name, "description", &result["styles"]["description"], |text| (theme.description)(text));
        expect_samples(name, "hint", &result["styles"]["hint"], |text| (theme.hint)(text));
        for (key, style) in [("label", &theme.label), ("value", &theme.value)] {
            for (i, want) in result["styles"][key].as_array().unwrap().iter().enumerate() {
                assert_eq!(Value::from(vec![style(SAMPLES[i], false), style(SAMPLES[i], true)]), *want, "{name} {key}[{i}]");
            }
        }
    }
}

fn install_keybindings(result: &Value) {
    let words = |value: &Value| match value {
        Value::String(one) => vec![one.clone()],
        Value::Array(many) => many.iter().map(|v| v.as_str().unwrap().to_string()).collect(),
        _ => Vec::new(),
    };
    let definitions: Vec<(String, KeybindingDefinition)> = result["defs"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(id, def)| (id.clone(), KeybindingDefinition { default_keys: words(&def["defaultKeys"]), description: def["description"].as_str().map(str::to_string) }))
        .collect();
    let user: Vec<(String, Vec<String>)> = result["user"].as_object().unwrap().iter().map(|(id, keys)| (id.clone(), words(keys))).collect();
    set_keybindings(KeybindingsManager::new(definitions, user));
}

/// Run `body` as a process on `platform` (Pi's `process.platform`).
fn on_platform(platform: &str, body: impl FnOnce()) {
    crate::keybinding_hints::DARWIN.with(|darwin| darwin.set(platform == "darwin"));
    body();
}

#[test]
fn key_text_matches_pi() {
    let _guard = STATE.lock().unwrap_or_else(|e| e.into_inner());
    for case in pi_cases("keyText") {
        let (name, result) = (case["name"].as_str().unwrap(), &case["result"]);
        install_keybindings(result);
        on_platform(result["platform"].as_str().unwrap(), || assert_eq!(key_text(case["args"][2].as_str().unwrap()), result["text"].as_str().unwrap(), "{name}"));
    }
}

#[test]
fn key_hint_matches_pi() {
    let _guard = STATE.lock().unwrap_or_else(|e| e.into_inner());
    for case in pi_cases("keyHint") {
        let (name, result) = (case["name"].as_str().unwrap(), &case["result"]);
        install_palette(&result["palette"]);
        install_keybindings(result);
        let a = case["args"].as_array().unwrap();
        on_platform(result["platform"].as_str().unwrap(), || assert_eq!(key_hint(a[4].as_str().unwrap(), a[5].as_str().unwrap()), result["text"].as_str().unwrap(), "{name}"));
    }
}

