#[test]
fn truncate_to_visual_lines_matches_pi() {
    for case in pi_cases("truncateToVisualLines") {
        let name = case["name"].as_str().unwrap();
        let a = case["args"].as_array().unwrap();
        let defined = |k: usize| a.get(k).filter(|v| v.get("$").is_none());
        let padding = defined(3).map_or(0, |v| v.as_i64().unwrap());
        let keep = match defined(4).and_then(Value::as_str) {
            Some("start") => VisualKeep::Start,
            _ => VisualKeep::End,
        };
        let got = truncate_to_visual_lines(a[0].as_str().unwrap(), a[1].as_i64().unwrap(), a[2].as_i64().unwrap(), padding, keep);
        let result = &case["result"];
        assert_eq!(got.visual_lines, strings(&result["visualLines"]), "{name}");
        assert_eq!(got.skipped_count as i64, result["skippedCount"].as_i64().unwrap(), "{name}");
    }
}
